 using Microsoft.VisualStudio.TestTools.UnitTesting;
 using Contoso.Text;

 namespace Contoso.Text.Tests;

 [TestClass]
 public sealed class StringFormatterTests
 {
     private readonly StringFormatter _formatter = new();

     [TestMethod]
     [DataRow("1234567890", "(123) 456-7890")]
     [DataRow("5551234567", "(555) 123-4567")]
     public void FormatPhoneNumber_ValidDigits_ReturnsFormattedNumber(string digits, string expected)
     {
         var result = _formatter.FormatPhoneNumber(digits);

         Assert.AreEqual(expected, result);
     }

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_StartsWithAreaCodeInParens()
     {
         var result = _formatter.FormatPhoneNumber("8005551234");

         Assert.StartsWith("(800)", result);
     }

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_EndsWithLastFourDigits()
     {
         var result = _formatter.FormatPhoneNumber("8005551234");

         Assert.EndsWith("1234", result);
     }

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_ContainsDash()
     {
         var result = _formatter.FormatPhoneNumber("8005551234");

         Assert.Contains("-", result);
     }

     [TestMethod]
     public void FormatPhoneNumber_NullInput_ThrowsArgumentNullException()
     {
         var ex = Assert.ThrowsExactly<ArgumentNullException>(() => _formatter.FormatPhoneNumber(null!));

         Assert.AreEqual("digits", ex.ParamName);
     }

     [TestMethod]
     [DataRow("123")]
     [DataRow("12345678901")]
     public void FormatPhoneNumber_InvalidLength_ThrowsArgumentException(string digits)
     {
         Assert.ThrowsExactly<ArgumentException>(() => _formatter.FormatPhoneNumber(digits));
     }

     [TestMethod]
     public void BuildGreeting_DefaultTitle_StartsWithDearMr()
     {
         var result = _formatter.BuildGreeting("Smith");

         Assert.StartsWith("Dear Mr.", result);
     }

     [TestMethod]
     public void BuildGreeting_DefaultTitle_EndsWithComma()
     {
         var result = _formatter.BuildGreeting("Smith");

         Assert.EndsWith(",", result);
     }

     [TestMethod]
     public void BuildGreeting_CustomTitle_ContainsTitle()
     {
         var result = _formatter.BuildGreeting("Johnson", "Dr.");

         Assert.Contains("Dr.", result);
         Assert.StartsWith("Dear Dr.", result);
     }

     [TestMethod]
     public void BuildGreeting_ContainsName()
     {
         var result = _formatter.BuildGreeting("Alice", "Ms.");

         Assert.Contains("Alice", result);
         Assert.AreEqual("Dear Ms. Alice,", result);
     }

     [TestMethod]
     [DataRow(null)]
     [DataRow("")]
     [DataRow("   ")]
     public void BuildGreeting_InvalidName_Throws(string? name)
     {
         Assert.Throws<ArgumentException>(() => _formatter.BuildGreeting(name!));
     }

     [TestMethod]
     [DataRow("Hello World", "hello-world")]
     [DataRow("  Multiple   Spaces  ", "multiple-spaces")]
     [DataRow("C# Is Great!", "c-is-great")]
     public void GenerateSlug_ValidTitle_ReturnsExpectedSlug(string title, string expected)
     {
         var result = _formatter.GenerateSlug(title);

         Assert.AreEqual(expected, result);
     }

     [TestMethod]
     public void GenerateSlug_Result_DoesNotStartWithDash()
     {
         var result = _formatter.GenerateSlug("--Leading Dashes");

         Assert.IsFalse(result.StartsWith('-'));
     }

     [TestMethod]
     public void GenerateSlug_Result_DoesNotEndWithDash()
     {
         var result = _formatter.GenerateSlug("Trailing Dashes--");

         Assert.IsFalse(result.EndsWith('-'));
     }

     [TestMethod]
     public void GenerateSlug_Result_MatchesSlugPattern()
     {
         var result = _formatter.GenerateSlug("Some Title! @#$ Here");

         Assert.MatchesRegex(@"^[a-z0-9]+(-[a-z0-9]+)*$", result);
     }

     [TestMethod]
     [DataRow(null)]
     [DataRow("")]
     [DataRow("   ")]
     public void GenerateSlug_InvalidTitle_Throws(string? title)
     {
         Assert.Throws<ArgumentException>(() => _formatter.GenerateSlug(title!));
     }

     [TestMethod]
     public void FormatCurrency_DefaultSymbol_StartsWithDollarSign()
     {
         var result = _formatter.FormatCurrency(9.99m);

         Assert.StartsWith("$", result);
     }

     [TestMethod]
     public void FormatCurrency_CustomSymbol_StartsWithSymbol()
     {
         var result = _formatter.FormatCurrency(19.99m, "€");

         Assert.StartsWith("€", result);
     }

     [TestMethod]
     [DataRow(10.5, "$10.50")]
     [DataRow(0, "$0.00")]
     [DataRow(1234.567, "$1234.57")]
     public void FormatCurrency_VariousAmounts_FormatsToTwoDecimalPlaces(double amount, string expected)
     {
         var result = _formatter.FormatCurrency((decimal)amount);

         Assert.AreEqual(expected, result);
         Assert.EndsWith(".50", _formatter.FormatCurrency(7.5m));
     }

     [TestMethod]
     public void FormatCurrency_NegativeAmount_ContainsMinusSign()
     {
         var result = _formatter.FormatCurrency(-5.00m);

         Assert.Contains("-", result);
         Assert.StartsWith("$-", result);
     }
 }

